import{z as o,x as l,o as e,c as s,q as B,j as t,D as a,d as n,s as r,S as i}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"银行间与交易所债市","description":"","frontmatter":{"title":"银行间与交易所债市","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-interbank-exchange-bond.md","filePath":"quant/cn-interbank-exchange-bond.md","lastUpdated":1791063341000}'),d={name:"quant/cn-interbank-exchange-bond.md"};function p(C,E,h,c,u,D){const A=l("Mermaid");return e(),s("div",null,[E[2]||(E[2]=B('<h1 id="银行间与交易所债市" tabindex="-1">银行间与交易所债市 <a class="header-anchor" href="#银行间与交易所债市" aria-label="Permalink to &quot;银行间与交易所债市&quot;">​</a></h1><div class="epigraph"><p>同一只信用债或利率债可以同时在银行间与交易所出现，但投资者、结算、回购与微观结构不同。跨市场利差可以是分割，也可以是不可交割的幻觉。</p><footer>—— 中国人民银行与财政部关于银行间债券市场的制度安排；沪深交易所债券交易规则；中国结算与上海清算所的托管结算分工；对照 Duffie 对市场分割与搜寻的讨论</footer></div><p><a href="/quant/cn-rates-market">上一课</a>写了利率债曲线。本课是中国进阶课序的收束：<strong>场所分割</strong>。银行间（CFETS、双边与经纪）服务商业银行等，托管多在上海清算所或中债登对应账户；交易所债（竞价、固定收益平台、质押式回购）服务经纪账户，中国结算。跨市场转托管有时间与资格。不要把两个场所的「收盘价」平均成一只债的真值。本课程不重写股票 LOB；交易所债券竞价是另一套产品规则。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分割产生价差：同一发行人、相近久期的交易所债与银行间债，因投资者不能无摩擦转移、回购利率不同、税费与可质押范围不同，可以持续偏离。问题是可交易性：转托管是否对你的账户开放、要多久、数量限制；以及两个价格是否同时可成交。用中债估值对交易所收盘算「套利」，往往忽略转托管时钟与最小包。失败则变成方向性信用或利率暴露。</p><p><span class="marginnote">直觉类比：把两个债市想成两家互不通用的会员制仓储——同一种货两边都有报价，但你把货从 A 仓挪到 B 仓要排队几天，还得具备 B 仓的会员资格。两边价差大不等于你能赚：等你排队挪完，价差多半早被别人收敛了。</span></p><p>交易所标准券回购与银行间质押式回购的折算率、利率、对手方不同。杠杆策略在两个场所的 haircut 不同，危机时交易所回购与银行间可以同时抽流动性但不同步，见 2013 钱荒与 2016、2022 等公开压力事件的场所差异（细节以当时公告为准）。股票量化团队若用交易所债券质押融资，必须把该 haircut 写进与股票涨跌停联合的现金计划。</p><h3 id="投资者准入" tabindex="-1">投资者准入 <a class="header-anchor" href="#投资者准入" aria-label="Permalink to &quot;投资者准入&quot;">​</a></h3><p>银行不能把银行间持仓当成交易所可卖，反之散户与许多公募的交易所仓不能直接当银行间报价。产品合同的投资范围决定宇宙。把「全市场信用债指数」当可交易，会包含你买不到的场所。点-in-time 成分须带 <code>venue</code>。</p><p><span class="marginnote">可转债主要在交易所竞价，与本课的银行间信用债不是同一微观结构。不要用银行间利差去解释转债折价。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>债券主数据：<code>isin/code</code>、托管场所、是否跨市场、转托管周期。报价：银行间用经纪商或 CFETS 可成交意向；交易所用竞价或综合协议。策略只在账户可达的场所下单。利差交易必须含转托管状态机：发起转托管后券在途，两侧都不可用，类似结算 fail。估值：中债/中证标明场所与样本券，回测声明。</p>',12)),(e(),t(i,null,{default:a(()=>[r(A,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%88%B8%E5%9C%A8%E4%BA%A4%E6%98%93%E6%89%80%E8%B4%A6%E6%88%B7%22%5D%20--%3E%20REQ%5B%22%E5%8F%91%E8%B5%B7%E8%BD%AC%E6%89%98%E7%AE%A1%22%5D%0A%20%20REQ%20--%3E%20TRANSIT%5B%22%E5%9C%A8%E9%80%94%EF%BC%9A%E4%B8%A4%E4%BE%A7%E5%9D%87%E4%B8%8D%E5%8F%AF%E5%8A%A8%22%5D%0A%20%20TRANSIT%20--%3E%7C%22T%2BN%20%E5%88%B0%E8%B4%A6%22%7C%20IB%5B%22%E8%BF%9B%E5%85%A5%E9%93%B6%E8%A1%8C%E9%97%B4%E8%B4%A6%E6%88%B7%EF%BC%8C%E5%8F%AF%E8%B4%A8%E6%8A%BC%22%5D%0A%20%20TRANSIT%20--%3E%7C%22%E8%B5%84%E6%A0%BC%E4%B8%8D%E7%AC%A6%20%2F%20%E6%94%BF%E7%AD%96%E7%AA%97%E5%8F%A3%E5%85%B3%E9%97%AD%22%7C%20FAIL%5B%22%E9%80%80%E5%9B%9E%E5%8E%9F%E8%B4%A6%E6%88%B7%EF%BC%8C%E6%95%9E%E5%8F%A3%E8%A3%B8%E9%9C%B2%22%5D%0A%20%20IB%20--%3E%20SPREAD%7B%22%E8%B7%A8%E5%B8%82%E5%9C%BA%E5%88%A9%E5%B7%AE%E4%BB%8D%E5%9C%A8%3F%22%7D%0A%20%20SPREAD%20--%3E%7C%22%E6%98%AF%E4%B8%94%E4%B8%A4%E8%BE%B9%E5%8F%AF%E6%88%90%E4%BA%A4%22%7C%20EXEC%5B%22%E6%89%A7%E8%A1%8C%E5%AF%B9%E9%94%81%22%5D%0A%20%20SPREAD%20--%3E%7C%22%E5%90%A6%22%7C%20ABORT%5B%22%E6%94%BE%E5%BC%83%EF%BC%9A%E6%88%90%E6%9C%AC%E5%90%9E%E5%99%AC%E4%BB%B7%E5%B7%AE%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<p><span class="marginnote">术语翻译：haircut（折扣率）就是质押融资时「100 元的债只当 70 元押」所砍掉的那 30%——交易所标准券回购与银行间质押式回购的折扣与利率不同，杠杆策略的真实融资能力由场所决定，不能把一处的杠杆倍数直接套到另一处。</span></p><p>与<a href="/quant/settlement-fails">结算失败</a>：银行间 DVP 与交易所结算周期不同，资金日终可用时点不同。跨市场策略的现金要按更慢的一条腿备付。</p><h3 id="价格发现谁领先" tabindex="-1">价格发现谁领先 <a class="header-anchor" href="#价格发现谁领先" aria-label="Permalink to &quot;价格发现谁领先&quot;">​</a></h3><p>活跃券可能在银行间，交易所跟估值；或相反，交易所可转债、公司债竞价更密。领先滞后必须用同步时钟与可成交报价，不能用两个收盘戳相减。这与股票 SIP/直连课同一精神：源与场所先声明。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>搜寻与准入使一价定律变成带摩擦的不等式。摩擦的时变来自：转托管政策、回购资格、风险事件下的投资者分割（银行 vs 基金）。利差扩大可以是理性的流动性溢价，不必是可锁套利。Duffie 式搜寻模型提供语言：对手难找时价差宽。中国的特点是场所由监管与托管账户划死，搜寻发生在场所内，场所之间是制度桥而不是连续 LOB。</p><p>工程课的 CCP：交易所债与银行间清算机构不同，瀑布与净额不共用。跨市场「中性」没有组合保证金，除非通过同一期货（国债期货）间接。</p>',7)),(e(),t(i,null,{default:a(()=>[r(A,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20IB%5B%22%E9%93%B6%E8%A1%8C%E9%97%B4%20%E8%AF%A2%E4%BB%B7%E4%B8%8E%E7%BB%8F%E7%BA%AA%22%5D%20--%3E%20Cust1%5B%22%E4%B8%AD%E5%80%BA%E7%99%BB%20%2F%20%E4%B8%8A%E6%B8%85%E6%89%80%22%5D%0A%20%20EX%5B%22%E4%BA%A4%E6%98%93%E6%89%80%20%E7%AB%9E%E4%BB%B7%E4%B8%8E%E5%B9%B3%E5%8F%B0%22%5D%20--%3E%20Cust2%5B%22%E4%B8%AD%E5%9B%BD%E7%BB%93%E7%AE%97%22%5D%0A%20%20Bridge%5B%22%E8%BD%AC%E6%89%98%E7%AE%A1%20%E8%80%97%E6%97%B6%E4%B8%8E%E8%B5%84%E6%A0%BC%22%5D%20--%3E%20IB%0A%20%20Bridge%20--%3E%20EX%0A%20%20Repo1%5B%22%E9%93%B6%E8%A1%8C%E9%97%B4%E5%9B%9E%E8%B4%AD%22%5D%20--%3E%20IB%0A%20%20Repo2%5B%22%E4%BA%A4%E6%98%93%E6%89%80%E6%A0%87%E5%87%86%E5%88%B8%E5%9B%9E%E8%B4%AD%22%5D%20--%3E%20EX%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供利用转托管窗口占用对手券源、或在分割市场之间制造虚假流动性的方法。具体转托管以登记结算机构现行指引为准。国际债、熊猫债、自贸区债另有账户。本课结束「A 股与债市续」课序；附录性质的论文与审计不插入主干。</p><p><span class="marginnote">常见误区：以为「同一只债两个价格」就必有一个是错的。两个价格都是各自场所内真实可成交的结果，偏差来自投资者不能无摩擦转移与回购资格差异——它是分割的定价，不是免费的错误；除非你的账户恰好两边可达且转托管即时，否则谈不上纠正它。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>银行间与交易所是分割的托管与投资者集合；跨市场价差须扣转托管时钟。</li><li>回购与结算不共用 CCP；杠杆与现金按场所分列。</li><li>估值源与可成交场所必须写入债券主键。</li><li>出处：银行间市场制度安排；沪深债券交易规则；中国结算与上清所；Duffie 搜寻与分割视角。</li></ul>',5))])}const f=o(d,[["render",p]]);export{m as __pageData,f as default};
